// Generic Metal host for portable kernels generated by spatial.kernel.
// usage: metal_run <msl_file> <kernel_name> <n> <reps> <out_file> <map|sum> [int:<v> | float:<v> ...]
// Buffers: 0 = output, 1 = n (int), 2.. = parameters in order.
// map: output uint[n*n]. sum: one uint64 partial sum per 16x16 threadgroup (the kernel reduces in threadgroup memory).
import Foundation
import Metal

func now() -> Double { return Double(DispatchTime.now().uptimeNanoseconds) / 1e9 }
func fail(_ m: String) -> Never { print("{\"ok\": false, \"error\": \"\(m)\"}"); exit(1) }

let a = CommandLine.arguments
if a.count < 7 { fail("usage") }
guard let src = try? String(contentsOfFile: a[1], encoding: .utf8) else { fail("cannot read msl") }
let name = a[2], n = Int(a[3])!, reps = max(1, Int(a[4])!), outPath = a[5], mode = a[6]
let sumMode = (mode == "sum")
let gx = (n + 15) / 16
guard let dev = MTLCreateSystemDefaultDevice() ?? MTLCopyAllDevices().first else { fail("no Metal device") }
let t0 = now()
let lib: MTLLibrary
do { lib = try dev.makeLibrary(source: src, options: nil) } catch {
    let msg = "\(error)".replacingOccurrences(of: "\"", with: "'").replacingOccurrences(of: "\n", with: " ")
    fail("shader compile failed: " + String(msg.prefix(300)))
}
guard let fn = lib.makeFunction(name: name) else { fail("kernel not found") }
let pipe = try! dev.makeComputePipelineState(function: fn)
let setupS = now() - t0
if sumMode && pipe.maxTotalThreadsPerThreadgroup < 256 { fail("device allows fewer than 256 threads per threadgroup") }
let outLen = sumMode ? gx * gx * 8 : n * n * 4
let out = dev.makeBuffer(length: outLen, options: .storageModeShared)!
let queue = dev.makeCommandQueue()!
var nn = Int32(n)

func run() -> Double {
    let t = now()
    let cb = queue.makeCommandBuffer()!
    let enc = cb.makeComputeCommandEncoder()!
    enc.setComputePipelineState(pipe)
    enc.setBuffer(out, offset: 0, index: 0)
    enc.setBytes(&nn, length: 4, index: 1)
    for (k, spec) in a[7...].enumerated() {
        let parts = spec.split(separator: ":", maxSplits: 1).map(String.init)
        if parts[0] == "int" { var v = Int32(parts[1])!; enc.setBytes(&v, length: 4, index: 2 + k) }
        else { var v = Float(parts[1])!; enc.setBytes(&v, length: 4, index: 2 + k) }
    }
    if sumMode {
        enc.dispatchThreadgroups(MTLSize(width: gx, height: gx, depth: 1), threadsPerThreadgroup: MTLSize(width: 16, height: 16, depth: 1))
    } else {
        let w = pipe.threadExecutionWidth
        let h = pipe.maxTotalThreadsPerThreadgroup / w
        enc.dispatchThreadgroups(MTLSize(width: (n + w - 1) / w, height: (n + h - 1) / h, depth: 1),
                                 threadsPerThreadgroup: MTLSize(width: w, height: h, depth: 1))
    }
    enc.endEncoding(); cb.commit(); cb.waitUntilCompleted()
    return now() - t
}
var times: [Double] = []
for _ in 0..<reps { times.append(run()) }
let data = Data(bytes: out.contents(), count: outLen)
do { try data.write(to: URL(fileURLWithPath: outPath)) } catch { fail("cannot write output") }
times.sort()
print("{\"ok\": true, \"device\": \"\(dev.name)\", \"gpu_s_median\": \(times[times.count / 2]), \"setup_s\": \(setupS)}")
